    cols = len(grid[0])

    five_row = None
    five_col = None
    for r in range(rows):
        if all(grid[r][c] == 5 for c in range(cols)):
            five_row = r
    for c in range(cols):
        if all(grid[r][c] == 5 for r in range(rows)):
            five_col = c

    non_five_rows = [r for r in range(rows) if r != five_row]
    non_five_cols = [c for c in range(cols) if c != five_col]

    n = len(non_five_rows)
