            board[i][j] = grid[r][c]
            if grid[r][c] != 0:
                values.add(grid[r][c])

    values = list(values)

    def is_valid(board, r, c, val):
        for i in range(n):
            if board[r][i] == val or board[i][c] == val:
                return False
        br, bc = (r // 2) * 2, (c // 2) * 2
        for i in range(br, br + 2):
            for j in range(bc, bc + 2):
                if board[i][j] == val:
                    return False
        return True

    def backtrack(board):
        for i in range(n):
            for j in range(n):
                if board[i][j] == 0:
                    for val in values:
                        if is_valid(board, i, j, val):
                            board[i][j] = val
                            if backtrack(board):
                                return True
                            board[i][j] = 0
                    return False
        return True

    backtrack(board)

    result = [row[:] for row in grid]
    for i, r in enumerate(non_five_rows):
        for j, c in enumerate(non_five_cols):
            result[r][c] = board[i][j]

    return result
